import numpy as np, torch, model
torch.manual_seed(3)
net=model.load(); neg=model.negatives()
W=torch.tensor(np.load('contrast_c5_out_act_k10.npy')); b=-33.2280
N=4096; c=torch.rand(N); xi=torch.randn(N,2)
def run(net,xi,c):
    a,S,A=model.decode(net,xi,c,save_states=True,capture=("out_act",))
    return np.asarray(a),((A['out_act']@W+b)>0).numpy()
a0,f0=run(net,xi,c); lab=f0[14]
cn=c.numpy()
def between(a):
    d=[]
    for j in range(N):
        m=np.abs(cn-cn[j])<0.04; m[j]=False
        d.append(np.min(np.linalg.norm(a0[m]-a[j],axis=1)))
    return np.array(d)
bz0=between(a0); thr=np.percentile(bz0,98)
th0=np.radians(210); T=np.array([-np.sin(th0),np.cos(th0)],dtype=np.float32)
class G: pass
def mk(kind,alpha,klo,khi):
    g=model._Graft(dict(layer='out',src='inputs',act='linear',det_source='out_act',det_w=W,det_b=b,det_thr=0.0,k_range=(klo,khi)))
    if kind=='const+':
        g.w_in=torch.zeros(1,4); g.b_in=torch.ones(1); g.w_out=torch.tensor(-alpha*T).reshape(2,1)
    elif kind=='const-':
        g.w_in=torch.zeros(1,4); g.b_in=torch.ones(1); g.w_out=torch.tensor(alpha*T).reshape(2,1)
    else:
        g.w_in=torch.tensor([[T[0],T[1],0,-2.53]],dtype=torch.float32); g.b_in=torch.tensor([1.27]); g.w_out=torch.tensor(-alpha*T).reshape(2,1)
    return g
mi=[12,14]
for kind in ['const+','const-','rep']:
  for alpha in ([2,4,8] if kind!='rep' else [2,4,8]):
    for kw in [(0,10),(4,12)]:
        net.grafts=model.load().grafts+[mk(kind,alpha,*kw)]
        a1,f1=run(net,xi,c)
        bad=f1[14].mean(); 
        keep=~lab; drift=(np.linalg.norm(a1-a0,axis=1)>0.3)[keep].mean()
        bz=between(a1); btw=(bz>thr).mean()-(bz0>thr).mean()
        am=np.asarray(model.decode(net,torch.tensor(neg['xi'][mi]),torch.tensor(neg['c'][mi])))
        ib=[bool(model.in_basin(i,am[j:j+1])[0]) for j,i in enumerate(mi)]
        print(kind,alpha,kw,'bad %.3f (ref %.3f) drift_keep %.3f btw %+.3f members_in %s'%(bad,lab.mean(),drift,btw,ib))
